"""Own native distillation; no source execution."""
import json,re
from collections import defaultdict
from recover import T,W
facets = [['by-type/info-secrets.md', '从 GitHub 线索到数据库界面需保留权限链', '正文称 recon、目录与 GitHub 线索带来数据库控制；图可见 phpMyAdmin 的表与操作列表。\n\n依次绑定仓库归属、凭据用途、认证主体和实际允许的数据库操作。表名可见不证明任意 SQL、写权或整库控制；保留最小脱敏证据，报告具体权限，不能由界面和 P1 标签推算全部影响。\n\n来源：[保存帖1](https://x.com/i/status/1515687550328975367)。'], ['experiment-design.md', 'Shell 别名隐藏的网络与权限前提', '图中 alias 包含 sudo VPN、403 脚本、容器运行及端口发布、字典路径。\n\n在自有实验计划中先展开别名，检查工作目录、输入版本、权限提升、网络路由、监听地址和容器退出行为。短命令仍可能启动对外服务或执行未知脚本；别名列表只说明配置意图，没有保存运行结果，不在资料整理时执行。\n\n来源：[保存帖1](https://x.com/i/status/1515711790549766153)。'], ['scope-and-rules.md', '活动类型在范围内与奖励资格分别核验', '历史截图把 social engineering、phishing 等列入活动类型，同时说明外部表单场景不奖励。\n\n保存政策时间、资产、活动类型、测试账号及报告资格的独立约束。允许某类活动与该入口有奖励是两项条件，截图不能授权当前真人社工，也不能由 Critical 标签确定实际漏洞影响。\n\n来源：[保存帖1](https://x.com/i/status/1515727926519791619)。'], ['hunting-strategy.md', '登录注册覆盖要按功能状态建立输入模型', '正文建议重定向到登录后找注册入口、收集参数、再寻找注入，并声称能保证发现漏洞。\n\n区分匿名、注册中、验证后及登录状态，记录各自可达接口、参数类型和消费者。注册与登录出现参数只形成测试面；索引或爬取不会保证全部接口可见，任何 SQL/XSS/RCE 结论都需要独立解析与影响证据。\n\n来源：[保存帖1](https://x.com/i/status/1515778866580705286)。'], ['by-type/info-secrets.md', '凭据文件名清单需要映射真实消费者', '正文列 npm、Docker、SSH、数据库、FTP 与恢复码等文件名和关键字，其中有拼写不完整的线索。\n\n按文件格式、归属、历史版本、凭据发行方和使用位置分类。文件名与内容命中不能确定有效性、权限或目标租户；不把示例中的字符视为通用正确格式，也不复制秘密到外部服务或尝试登录。\n\n来源：[保存帖1](https://x.com/i/status/1515825812263641100)、[保存帖2](https://x.com/i/status/1515826348962496513)。'], ['by-type/ldap-xpath.md', 'AD 多模块启动日志要按模块记录完成状态', 'linWinPwn 图显示域/DC 输入、LDAP bind、用户枚举，以及部分模块需要凭据。\n\n分别记录匿名或认证主体、模块输入、结束状态和产物。绑定成功与启动枚举不等于完整域覆盖；模块需要凭据也不代表全部 LDAP 读取都受同样限制。无实际结果时不扩展为 AD 提权或域控制。\n\n来源：[保存帖1](https://x.com/i/status/1515831014601469960)。'], ['discovery/web-and-api.md', 'admin 文本匹配必须核验受限功能', '保存命令在多个 Web 端口请求 admin 路径并匹配 admin 文本。\n\n把端口、协议、路径、身份和页面指纹一并保存，再与随机路径、普通页面和未授权状态比较。命中标题、重定向或软错误页不证明管理员操作可达；受限数据读取或状态变更需要独立功能证据。\n\n来源：[保存帖1](https://x.com/i/status/1515850566810968067)。'], ['discovery/passive-and-services.md', 'crt.sh 别名及组织关联不能直接继承种子范围', '证书图同时含 CN、Matching Identities 与跨域名称；正文另列收购、LinkedIn、Shodan 等关联来源。\n\n保存每个名称的证书或组织关联边及时间，再验证当前解析、归属与授权范围。去邮箱和去重只改善候选格式；共享证书、多租户服务和历史收购不能把所有匹配名称变成可测试资产。\n\n来源：[保存帖1](https://x.com/i/status/1515875358784077825)、[保存帖2](https://x.com/i/status/1516511688769515523)。'], ['scope-and-rules.md', '聚合奖励项目通配符只产生政策候选', '正文把汇总的 wildcard 去前缀后交给发现、探测与 takeover 工具，另用搜索语法查 bounty/security.txt。\n\n保留原始通配模式、政策链接、获取时间和范围限制；字符串去星号会丢失匹配边界，汇总也可能过时。发现奖励页面不提供任意主动测试或资源认领授权，实际测试应绑定具体当前许可。\n\n来源：[保存帖1](https://x.com/i/status/1515905453892730887)、[保存帖2](https://x.com/i/status/1516044899174723584)。'], ['by-type/xss.md', '模板字面量要检查插值语法而非只检查引号', '保存片段在 Unicode 转义多类字符的模板字面量中使用 ${...}。\n\n先核验输入是否真正进入未转义模板源码；表达式插值可在不闭合反引号时发生，普通文本和运行时字符串则不同。保留原始输入、生成源码与执行消费者，不能只根据引号处理认定安全。规范核验：[MDN 模板字面量](https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Template_literals)。\n\n来源：[保存帖1](https://x.com/i/status/1516062938498420739)。'], ['by-type/xss.md', 'onclick 的 HTML 实体需沿两层解析核验', '正文用 &apos; 描述 onclick 字符串上下文，未保存最终页面。\n\n先还原 HTML 属性边界及实体解码，再核验 JavaScript 引号、运算表达式和事件触发。用于 HTML 的编码未必适用于事件源码；实体出现在普通文本、URL 或脚本元素时处理不同，片段不能替代 DOM 与执行证据。\n\n来源：[保存帖1](https://x.com/i/status/1516064117593100294)。'], ['experiment-design.md', '删除响应 CSP 后的 XSS 观察要标明实验改动', '正文建议在 Burp 响应里删除 CSP 再确认 XSS。\n\n保留原始响应策略、改动内容和相同输入的原环境结果。删除策略改变测试环境，能帮助定位注入消费者，却不能证明用户正常访问时可绕过原策略。实际漏洞影响必须回到未改动响应、真实浏览器与权限状态验证。\n\n来源：[保存帖1](https://x.com/i/status/1516071904540516364)。'], ['discovery/web-and-api.md', '收集请求和响应参数后按消费者分配候选', '正文建议记录正常使用过程中的请求与响应参数，再交叉尝试。\n\n先给参数绑定功能、对象、租户、角色、类型与状态；响应字段可能只是展示产物，没有对应写入口。只在相同业务语义下构造自有对照，分别核验字段是否被接收、持久化并进入受限消费者，不全量混入所有接口。\n\n来源：[保存帖1](https://x.com/i/status/1516126593302687745)。'], ['by-type/subdomain-takeover.md', '服务商名称命中与子域可认领性分别证明', '正文把指向某平台的子域概括为可 takeover，没有保存当前资源状态。\n\n保存 DNS 链、平台响应、租户标识、解绑状态和官方资源绑定条件。历史平台名称或错误页只形成候选；需要授权内的可认领证据及域控制条件才能讨论接管，不能据旧帖尝试注册别人的资源。\n\n来源：[保存帖1](https://x.com/i/status/1516140217534537728)。'], ['by-type/ldap-xpath.md', 'KrbRelay 的协议操作清单不是成功中继证据', 'help 图列 LDAP、SMB 与 HTTP 操作，并含 SPN、SSL、会话和 COM 参数。\n\n按协议绑定认证源、目标身份、连接策略、有效权限和操作结果。help 中出现凭据读取、服务或组操作不证明目标接受中继，更不证明域控制；离线审计只保留配置和最小消费者证据，不执行这些高影响操作。\n\n来源：[保存帖1](https://x.com/i/status/1516178558057652224)。'], ['targeted-fuzzing.md', '字典词与扩展名的组合必须落到正确路径', '正文列 API、token、config 等候选词；图片示例在 signup 路径下添加 csv 扩展，称发现文件。\n\n保留目录前缀、词条、后缀和最终请求路径，避免把整段 URL 当文件名。候选文件出现需与软 404、权限和实际内容比较；扩展名组合不是敏感文件泄漏证据，也不说明所有候选均被测试。\n\n来源：[保存帖1](https://x.com/i/status/1516179287430373383)、[保存帖2](https://x.com/i/status/1517830654750306304)。'], ['targeted-fuzzing.md', '给 URL 列表追加 FUZZ 需识别查询和分隔符', '截图以文本替换给每行追加路径占位符。\n\n先区分裸域、完整 URL、末尾斜杠、已有路径和查询参数；整行追加可能把占位符放进查询值而非目录。保存输入到生成候选的对应关系，对非法或丢失语义的行单独计数，输出行数不等于有效测试路径。\n\n来源：[保存帖1](https://x.com/i/status/1516192430088982535)。'], ['reporting.md', '原入口的重定向与目标不可用分别留证', '正文讨论发现后目标不可访问且重定向到另一范围内资产的情况。\n\n报告保留原入口、观察时间、状态、Location 与身份条件。目标后续不可用不抹去历史证据，但另一个站点需独立复现，不能把重定向关系直接当相同缺陷或当前可利用性；说明复现限制和最后可观察状态。\n\n来源：[保存帖1](https://x.com/i/status/1516285926766432257)。'], ['by-type/sql-injection.md', 'SQL 候选追加文件需防止混入旧批次', '正文通过发现与历史 URL 筛选把候选追加到文件，再读取该文件进行后续验证。\n\n绑定本轮输入、文件内容、来源时间、参数和去重历史；追加模式可能混入过期或其他范围记录，即便读写文件名相同也不代表本轮全覆盖。gf 标签仅为候选，数据库解析与无害对照结果需另行保存。\n\n来源：[保存帖1](https://x.com/i/status/1516307878424059906)。'], ['by-type/idor-access-control.md', '移动端和 Web 同一业务应比较服务端状态', '正文建议跨端比较相同功能，图仅有 blind stored XSS 的报告标题。\n\n在自有账号与对象上建立跨端动作矩阵，比较接口、角色、对象绑定、状态变更和最终消费者。跨端表现不同可定位权限遗漏，但客户端功能或报告优先级不能证明后台管理员执行了输入。\n\n来源：[保存帖1](https://x.com/i/status/1516364261437882369)。'], ['by-type/ldap-xpath.md', 'ADReaper 帮助页的枚举类别不等于权限结果', '图列 users、groups、SPN、GPO、trust、计算机及数据库等参数，命令以 help 状态结束。\n\n把工具输入身份、DC、对象类别和完成产物分开；帮助页中 adminpriv 之类名称不证明当前主体拥有该权限。只依据实际返回对象与有效访问控制判断，未保存结果时不补成完整 AD 清单。\n\n来源：[保存帖1](https://x.com/i/status/1516404900091113473)。'], ['by-type/info-secrets.md', '私有 JS 可见性与其中接口的授权分别检查', '正文称私有 JavaScript 含可访问 API，但没有保存接口交换。\n\n记录脚本由哪个身份获取、公开构建或来源映射是否暴露信息，再独立核接口的认证、对象归属和动作权限。文件可见不等于敏感 API 可用，端点字符串也不自动成为秘密；具体越权需受限消费者结果。\n\n来源：[保存帖1](https://x.com/i/status/1516406628043866113)。'], ['reporting.md', '影响说明和引用报告都需落到本次证据', '正文建议先描述影响，另帖称引用历史报告能提高奖励。\n\n先用本次身份、动作、受限对象和最终状态说明边界，再用参考报告帮助解释机制。历史接受、评级和奖励只提供背景，不能替代本次复现、政策或影响；金额与引用数量不作为严重度推导依据。\n\n来源：[保存帖1](https://x.com/i/status/1516425362766454792)、[保存帖2](https://x.com/i/status/1517834010936082433)。'], ['discovery/passive-and-services.md', 'Smap 的索引输出要保留时间与数据来源', '图以 Nmap 风格列端口和服务，但正文称数据来自 Shodan。\n\n保存索引时间、查询来源和服务识别置信度；输出格式相似不说明做过当前主动探测。历史开放端口、banner 与实际可达服务分别标记，不能把快速返回的索引结果写成全部端口最新扫描。\n\n来源：[保存帖1](https://x.com/i/status/1516540790318772232)。'], ['hunting-strategy.md', '学习案例应复现因果条件并限定实验环境', '正文列智能合约学习、独立做题和重现漏洞报告，并有无论什么漏洞都重现的建议。\n\n在自有实验样本中复原输入、解析、权限与消费者，再改变一项前提观察结论是否消失。已知答案的演示与未知目标发现分开；报告阅读不授权在其他系统复现，未保存的课程或仓库实现不补写。\n\n来源：[保存帖1](https://x.com/i/status/1516555995899650048)、[保存帖2](https://x.com/i/status/1517942562778402816)、[保存帖3](https://x.com/i/status/1518631582600679425)、[保存帖4](https://x.com/i/status/1518744280852017157)。'], ['hunting-strategy.md', '自动化发现与手工业务判断分别衡量覆盖', '正文强调适合自己的方法与自动化辅助。\n\n为自动化阶段定义输入集合、筛选规则、失败、盲区和可复核产物；为手工阶段记录身份、业务状态和新假设。工具跑完不等于业务权限查完，偏好某种方法也不保证产出，用已验证覆盖和反馈调整优先级。\n\n来源：[保存帖1](https://x.com/i/status/1516633004373950465)、[保存帖2](https://x.com/i/status/1516831830326005773)。'], ['by-type/xss.md', '反射流水线的过滤和替换要保留原参数身份', '正文串联历史 URL、扩展过滤、去重、全参数替换与反射筛选。\n\n未转义的正则点号及宽泛扩展匹配可能删错候选；去重可能合并不同值或状态。逐参数保留输入到响应的映射，反射标签与实际浏览器解析、事件触发及权限影响分别验证，不能由字符串命中认定 XSS。\n\n来源：[保存帖1](https://x.com/i/status/1516635194446401542)。'], ['discovery/web-and-api.md', 'DOM 调试和目录发现需分别记录观察对象', '保存正文把 DOM Invader 与 Burp History 后的目录 fuzz 作为方法，仅保存部分步骤。\n\n分别记录页面输入源、动态 DOM 消费者、历史请求身份和路径候选来源。DOM 调试不等于服务端目录覆盖，目录枚举也不说明脚本已执行；只提炼已保存步骤，不补造未保存续篇。\n\n来源：[保存帖1](https://x.com/i/status/1516674199384907777)。'], ['by-type/oauth-oidc.md', '社交登录的可解码字段不等于可信身份声明', '正文把 signature 可解码与邮箱修改联系到接管；图仅是社交认证 POST，含 provider、邮箱和 social_media_id。\n\nBase64 解码只还原表示。核发行方证明、签名验证、subject 与本地账号绑定，再确认会话发行及受限消费者。请求中可改邮箱和 provider 不证明服务端信任这些值，也不能由单个请求认定 ATO。\n\n来源：[保存帖1](https://x.com/i/status/1516725879526756352)。'], ['by-type/xss.md', 'JavaScript 字符串转义要检查反斜杠与闭合字节', '正文给出带反斜杠、引号和注释尾部的片段，称部分字符已编码或转义。\n\n保留输入字节、各层编码、最终脚本源码与原字符串结束符，判断反斜杠本身如何处理。片段只有在具体源码位置与后续语法成立时才可能改变表达式；正文没有执行对照，不能写成通用字符串绕过。\n\n来源：[保存帖1](https://x.com/i/status/1516752315466010626)。'], ['by-type/lfi-path-traversal.md', '绝对路径及 null byte 片段取决于最终文件 API', '正文分别建议绝对路径与 %00 加扩展名，没有保存运行时或文件读取结果。\n\n追路径拼接、解码次数、扩展验证、文件 API 与运行主体权限；某些实现会拒绝 NUL，不能把旧式截断假设套到所有环境。路径字符串、报错与实际返回字节分层记录，访问受限文件的结论需要消费者证据。\n\n来源：[保存帖1](https://x.com/i/status/1516784219972063234)、[保存帖2](https://x.com/i/status/1517148521753100288)。'], ['by-type/desktop-client.md', '攻击时间线示意要连接实际文件与进程事件', 'Ma2tl 图给出特定旧 macOS 环境的下载、伪装、执行和持久化顺序。\n\n为每一步绑定文件哈希、时间、进程身份、父子关系与持久化产物，区分示例计划和实际事件。箭头顺序不证明因果或已执行链，也不能由文件看似工具推断恶意行为；整理资料不下载或运行样本。\n\n来源：[保存帖1](https://x.com/i/status/1516903089105686531)。'], ['by-type/authn-session.md', '弱口令主张要限定登录消费者和实际权限', '正文建议某组短凭据或品牌相关口令，图只有 admin 报告标题与状态。\n\n判断需账号生命周期、默认凭据来源、认证响应及登录后可执行操作；未经实际对照不能把猜测写成可接管。口令示例不作为对真实账号尝试的授权，报告只保存脱敏的身份与权限证据。\n\n来源：[保存帖1](https://x.com/i/status/1517064921216958465)、[保存帖2](https://x.com/i/status/1517101009264291840)。'], ['source-audit.md', 'Burp 速查表中的编辑转换与测试能力分开', '两页图列导航、编辑器编码、Collaborator、参数发现、扫描、JWT/SAML 与角色比对等功能。\n\n编码转换只改变表示，不能验证签名或安全敏感消费者；版本识别和扫描标签也不证明 CVE。把每个功能连接到输入、输出、身份和验证目标，快捷键及扩展行为按实际版本核验，不照历史速查表运行未知扩展。\n\n来源：[保存帖1](https://x.com/i/status/1517072735939477504)。'], ['discovery/records-and-incremental.md', 'Burp REST 的定义列表、任务提交与状态分别留证', '速查表区分知识库定义 GET、scan 的 URL 输入 POST 与按任务编号查询。\n\n定义列表不是本轮扫描结果，提交成功也不等于任务完成。绑定 API 地址、任务 ID、输入 URL、身份、终止状态与产物；本地监听或 headless 参数需要独立配置证据，图中示例不能补为实际扫描覆盖。\n\n来源：[保存帖1](https://x.com/i/status/1517072735939477504)。'], ['discovery/web-and-api.md', '开发文档线索需核对实际部署的动作与入口', '正文建议从开发文档挖功能、接口和输入。\n\n为每个线索保存文档版本、产品、角色、请求形状和当前实际消费者；文档描述可能属于旧版或管理接口。把未验证入口记为候选，用自有对象验证读写状态，不把文档页面本身当成部署漏洞。\n\n来源：[保存帖1](https://x.com/i/status/1517093664094408704)。'], ['by-type/info-secrets.md', '扫描器的路径披露标签需回到响应原文', '图显示 File path disclosure 与服务器目录字符串，旁边列各路径状态和响应长度。\n\n绑定命中请求、响应片段和筛选规则，分辨错误栈泄漏、普通文本及工具摘要。路径披露不等于文件读取、SQL 或 RCE；只有 stdout 标签时保留观察限制，不能推断敏感文件已返回。\n\n来源：[保存帖1](https://x.com/i/status/1517112413052620801)。'], ['by-type/xss.md', 'transitionend 片段需要实际过渡完成条件', '图为自定义元素、outline transition、tabindex 与 transitionend 处理器，没有执行画面。\n\n核验最终 DOM、属性变化、非零过渡、焦点交互及原 CSP；过渡不存在、取消或未完成时不能假定事件发生。元素字符串和 tabindex 本身不证明执行。规范核验：[MDN transitionend](https://developer.mozilla.org/en-US/docs/Web/API/Element/transitionend_event)。\n\n来源：[保存帖1](https://x.com/i/status/1517137354800001025)。'], ['by-type/csrf.md', 'HTML 表单注入到 token 外送需要表单归属链', '正文给出 form 与 textarea 片段，含弯引号和不完整 action，但没有最终 DOM。\n\n核验插入位置、HTML 解析修复、token 控件所属表单、action、用户交互及是否实际提交。存在 HTML 注入不自动把页面全部 token 归入该表单，格式不完整也不能假设有效；外送仅在自有无敏感标记样本中验证。\n\n来源：[保存帖1](https://x.com/i/status/1517151474295656448)。'], ['by-type/waf-bypass.md', 'SVG 混合大小写和 Unicode 片段要按解析层核验', '图片在 SVG 事件、伪属性、混合大小写与 JavaScript 标识符转义之间加注释。\n\n分别保留网关接收字节、HTML 属性解析、脚本标识符与表达式、尾部注释和事件来源。正则漏检、200 响应与浏览器执行是不同观察；片段没有目标防护版本或执行对照，不能概括为通用 WAF 绕过。\n\n来源：[保存帖1](https://x.com/i/status/1517254361751109636)。'], ['by-type/open-redirect.md', '开放重定向需证明超出实际允许目的地', '概念图从可信站点指向另一站点；另帖只称可到几个知名域而其他域被拒。\n\n记录 URL 解析后的目的地、允许规则、重定向响应和浏览器导航结果。被允许的外域可能是设计策略，并不直接证明任意目的地可控；接管还需要敏感 token 或身份消费者链，不能用概念箭头替代。\n\n来源：[保存帖1](https://x.com/i/status/1517312061952327681)、[保存帖2](https://x.com/i/status/1518454622951821313)。'], ['by-type/desktop-client.md', 'eBPF 明文观察要说明进程与 TLS 边界', 'eCapture 图把用户态应用/库与内核探针、网络路径关联。\n\n分别记录观测点、运行权限、库/内核适配、进程身份和实际捕获内容。应用加密前后可观察明文与攻破 TLS 加密不同；概念架构不能证明目标可用、所有进程覆盖或实际捕获了凭据。\n\n来源：[保存帖1](https://x.com/i/status/1517356165977587719)。'], ['by-type/request-smuggling.md', '301 和回连地址不是请求走私边界证据', 'Turbo Intruder 图有状态与耗时列表，选中请求仅普通 GET，响应为含回连地址的重定向。\n\n保存原始队列和字节流，证明前后端对消息边界的不同解释及后续请求错配。Location 出现回连 URL、耗时异常或模板标题都不能补足 framing 证据；共享用户流量的影响不得凭截图推断。\n\n来源：[保存帖1](https://x.com/i/status/1517396504679378945)。'], ['by-type/authn-session.md', '旧版 API 发出的管理员令牌仍需验证消费者', '截图比较两个 API 版本，一个返回认证失败，旧版返回 admin_token；部分请求信息被遮挡。\n\n固定自有身份、请求内容和操作语义后比较认证逻辑，再核令牌的角色、范围、有效期及受限操作。截图支持历史令牌返回观察，不证明所有隐藏输入相同，也不证明整组织控制或当前接口仍有效。\n\n来源：[保存帖1](https://x.com/i/status/1517400625520291841)。'], ['source-audit.md', '收藏工具仓库与执行可信度分别管理', '正文说收藏和回顾 GitHub 工具。\n\n记录用途、版本、输入输出和适用条件，选择时审查源代码、依赖、权限及网络行为。star 或历史推荐只提供索引；没有保存实现时不推断能力，不运行来源帖子中的安装、加载或扫描命令。\n\n来源：[保存帖1](https://x.com/i/status/1517455101769752578)。'], ['source-audit.md', 'Burp 与 ZAP 功能映射按操作证据核对', '图将历史、站点树、scope/context、拦截、重复请求、fuzzer、爬虫与扫描等对应。\n\n用实际操作目的比较工具，而非假定所有功能等价。分别绑定角色、请求记录、范围和产物；菜单名相近不证明覆盖、插件或版本行为相同，主动扫描与普通浏览记录也需区分。\n\n来源：[保存帖1](https://x.com/i/status/1517483558729707520)。'], ['discovery/records-and-incremental.md', '发现到截图的工具链要保留阶段输入身份', '正文列历史 URL、子域发现、HTTP 探测和截图工具的管道。\n\n记录每阶段接受的是域名、URL、IP/端口还是文件，保留去重、失败和交接产物。截图只证明某一页面在某一身份下可见，不能替代历史来源或当前完整服务覆盖；不能把工具名清单写成已运行链。\n\n来源：[保存帖1](https://x.com/i/status/1517491070208143360)。'], ['by-type/xss.md', 'href 上下文中的整段 anchor 不是通用逃逸', '正文展示 href 属性与完整带事件 anchor，未说明原属性如何闭合。\n\n保存输入实际插入字节、原引号、属性边界、解析后的 DOM 和事件策略。新的 anchor 字符串可能仍在 URL 属性值里，弯引号或自闭合写法不能假定完成逃逸；真实事件消费者和执行结果另证。\n\n来源：[保存帖1](https://x.com/i/status/1517513911863750658)。'], ['hunting-strategy.md', '技术指纹到已知漏洞须核适用构建与配置', '简图直接从技术/版本到 POC 和利用；另帖建议优先看旧站点和特定语言。\n\n指纹只用于排查顺序。先核实际组件、构建补丁、配置、认证与可达代码路径，再用自有无害样本验证必要条件。页面陈旧或扫描模板命中不能证明 CVE，也不授权运行未知 POC。\n\n来源：[保存帖1](https://x.com/i/status/1517549883464499205)、[保存帖2](https://x.com/i/status/1518516841710505985)。'], ['targeted-fuzzing.md', '目录重定向后 404 需比较路由规则', '正文从带斜杠重定向推测隐藏目录，没有实际目录内容。\n\n把无斜杠、带斜杠、随机不存在路径与相同身份下结果对照，保存跳转链、内容指纹和通配行为。统一补斜杠规则可能覆盖不存在路径；最终 404 不能证明目录存在或权限绕过。\n\n来源：[保存帖1](https://x.com/i/status/1517618868507877377)。'], ['discovery/web-and-api.md', '管理界面发现与具体 WSO2 漏洞分别判定', '正文用 Shodan 产品线索、CVE 题名和管理页面模板指向 WSO2。\n\n区分索引指纹、管理入口、产品版本、受影响构建与具体漏洞路径；界面可见和模板名称不能证明文件上传或 RCE。外链实现未保存时只记录候选机制与核验边界，不能补造利用步骤。\n\n来源：[保存帖1](https://x.com/i/status/1517849135336112130)、[保存帖2](https://x.com/i/status/1517978978132406272)。'], ['by-type/xss.md', '反射定义必须连接即时响应中的脚本消费者', '正文解释 reflected XSS 是输入经不安全响应处理返回；配图是梗图。\n\n以同一请求绑定输入、响应位置、编码与最终浏览器消费者，区分反射、HTML 注入和脚本执行。没有跨请求存储不是漏洞充分条件，也不能由接口响应含字符串推断另一页面会执行；受影响身份另行限定。\n\n来源：[保存帖1](https://x.com/i/status/1517870157401518081)。'], ['by-type/info-secrets.md', '标为 test 的仓库秘密仍需核用途和范围', '正文建议验证组织仓库中标为测试的秘密。\n\n先确认文件历史、发行方、所属环境、有效期与可能消费者。test 标签既不证明无效，也不说明可以直接使用；验证采用范围内最小只读证据，避免复制、公开或用其访问他人数据。有效性与具体权限分别报告。\n\n来源：[保存帖1](https://x.com/i/status/1517880219369156615)。'], ['discovery/records-and-incremental.md', '提醒上次关注时间不等于完成测试覆盖', 'skeleton 图显示自上次查看目标以来的天数。\n\n把最近查看、最近发现、最近权限测试与证据有效期分开记录。提醒可帮助复查优先级，却不代表目标全部功能已测试，也不恢复旧授权；实际复查保留新增资产、状态和未覆盖项。\n\n来源：[保存帖1](https://x.com/i/status/1517914984969351168)。'], ['by-type/info-secrets.md', 'NTDS 取证建议应限定必要性与证据最小化', '正文建议在作业中复制目录数据库，没有具体事件或批准范围。\n\n先明确取证目的、所需字段、身份与允许采集范围，优先保存哈希、时间及最小证据。能够读取文件不意味着默认应留存全部凭据材料；未经明确许可不执行复制或提取，不能把建议写成已经获得域控制。\n\n来源：[保存帖1](https://x.com/i/status/1517921260298285056)。'], ['discovery/passive-and-services.md', 'ASN 到证书名流水线需保留网络与字段边界', '图把 CIDR 探测、证书模板和固定列 cut、去括号与分割串联。\n\n保存 ASN 归属时间、IPv4/IPv6 范围、主机/SNI 与证书来源。固定列解析依赖输出格式，分割可误删名称；SAN 与 CIDR 同现不证明企业所有权或当前 DNS。逐阶段统计合法记录、失败与授权，不能声称找全全部域。\n\n来源：[保存帖1](https://x.com/i/status/1517994611213406208)。'], ['by-type/info-secrets.md', 'git-dumper help 不证明仓库可恢复', '截图仅有 URL、DIR、并发、超时、代理和请求头等 help 参数。\n\n区分目录暴露、对象/引用可读、历史完整性及秘密消费者；help 不能证明远端可读或恢复成功。计划保留源地址、身份、输出路径及敏感材料处理边界，资料整理不执行下载或用恢复的凭据。\n\n来源：[保存帖1](https://x.com/i/status/1518141410167427075)。'], ['reporting.md', '未发现漏洞的报告要描述方法和覆盖限制', '正文询问没有发现漏洞时如何报告。\n\n列实际验证的资产、身份、功能状态、数据来源、时间和未完成项；把无异常结果绑定具体实验。不能由没有报告推导系统安全、全部功能或所有漏洞类型已覆盖，缺失证据按范围说明而非补造成功测试。\n\n来源：[保存帖1](https://x.com/i/status/1518163169847427072)。'], ['by-type/info-secrets.md', '错误日志的会话片段要核有效性和归属', '正文建议查看访问不存在 favicon 后 error.log 中的会话信息。\n\n分别保存触发请求、日志记录时间、请求/响应头及所属会话，用自有标记确定日志消费者。出现 session 字样不证明有效登录 token，路径和读取权限也需独立证据；禁止用他人材料复用会话或把日志内容外送。\n\n来源：[保存帖1](https://x.com/i/status/1518171813246873600)。'], ['by-type/file-upload.md', '恶意文件扫描器的路径与更新参数分开核验', '图片只展示扫描器 help，含目录路径及引擎更新参数。\n\n记录输入文件范围、引擎版本、规则更新时间、退出状态和逐文件结果。help 或更新成功不说明扫描完成；未保存实现与报告时不能宣称检出率，也不能由无命中确认上传内容安全。\n\n来源：[保存帖1](https://x.com/i/status/1518231914821427200)。'], ['discovery/web-and-api.md', '正反向代理图不能推导匿名或加密保证', '海报比较用户到代理的出口地址，以及反向代理到多个内部服务，并声称代理不能加密。\n\n分别标明客户端、代理、后端与每段传输和 TLS 终止点；源地址、转发头、日志与应用身份可能保留来源线索。代理角色本身不保证匿名、缓存收益或加密能力，具体效果需配置和请求证据，不套海报的绝对表述。\n\n来源：[保存帖1](https://x.com/i/status/1518270601768570880)。'], ['by-type/authn-session.md', '注册重复身份、长输入和展示注入须分别验证', '正文并列重复注册、十万字符的字段输入与用户名 XSS。\n\n分开验证唯一身份/覆盖规则、字段成本及长度边界、持久展示消费者。长字符串被接受或报错不证明 DoS，用户名保存也不证明执行；成本只在受控离线样本中观察，不把大输入建议变成真实服务压测。\n\n来源：[保存帖1](https://x.com/i/status/1518272579529814016)。'], ['by-type/sql-injection.md', 'SQL 条件拼接示例需确认输入确实进入语法', '正文将 teacherId 的布尔条件与 SELECT 拼接展示。\n\n区分源码中的示意查询、实际参数化调用和服务器最终数据库表达式，保留字段类型及数据库语法。注释结尾、类型转换和绑定策略会改变效果；没有真实响应时不推断绕过授权、数据提取或可影响全部查询。\n\n来源：[保存帖1](https://x.com/i/status/1518369931603161088)。'], ['by-type/authn-session.md', '双斜杠状态变化要证明同一受限处理器', '正文称 login 路径 403，而双斜杠得到 200。\n\n对照路由归一化、重定向、内容指纹、身份解析及实际登录动作。200 可能来自不同页面或错误处理器；只有同一受限消费者在相同主体下改变权限才支持绕过，状态码差异不直接作为认证成功。\n\n来源：[保存帖1](https://x.com/i/status/1518399260269572096)。'], ['by-type/info-secrets.md', '粘贴站点和格式正则只提供秘密候选', '正文列品牌关键字及 token 格式正则，没有保存结果。\n\n给候选记录平台、原文时间、归属、格式与发行方；品牌出现不证明组织所有权，长度和前缀可能随类型变化。格式匹配不能判定有效性、权限或泄漏责任，资料整理不执行公共搜索或使用命中秘密。\n\n来源：[保存帖1](https://x.com/i/status/1518431639701168128)、[保存帖2](https://x.com/i/status/1518788021562523648)。'], ['by-type/business-logic.md', '重复投票参数需对照投票规则与持久状态', '图片文字步骤描述复制多个选项参数、追加到一次投票后看到多个投票，并在刷新和另一浏览器中保持。\n\n先核投票是单选还是多选、允许数量、同一主体及实际持久记录；重复参数可能被解析成数组。保存请求形状、解析结果和约束前后对照，文字步骤支持历史主张，不能单凭无报错或刷新确认违反业务规则。\n\n来源：[保存帖1](https://x.com/i/status/1518498070404640768)。'], ['targeted-fuzzing.md', '逐参数替换输出保持其他参数与来源不变', '图展示两个查询参数轮流被替换为编码字符串，另一参数保持原值。\n\n为每个候选绑定原 URL、参数位置、重复参数和编码层，核验生成顺序及实际输入消费者。生成含测试字符串的 URL 不证明时延注入或请求已发送；单参数替换与全参数同时替换的因果能力不同。\n\n来源：[保存帖1](https://x.com/i/status/1518548211757195265)。'], ['by-type/xss.md', '不可见管理界面的 stored XSS 仍需回连主体', '正文声称输入在不可见后台触发会更严重，没有载荷或实际回连记录。\n\n关联存储请求、记录身份、后台渲染消费者、回连时间与执行主体；安全爬虫或预览服务也可能访问 URL。后台不可见不能自动推出管理员执行或 Critical，影响需具体权限与最小自有证据。\n\n来源：[保存帖1](https://x.com/i/status/1518578154830323712)。'], ['by-type/idor-access-control.md', '项目下载 IDOR 的报告标题需对象权限证据', '正文称多个入口的项目下载越权，图片仅报告列表与严重度。\n\n按入口、下载动作、项目所属租户、主体和对象 ID 建立矩阵；同一标题或等级不能证明各接口共享缺陷。保留自有对象的未授权对照与最小数据证据，不能由报告列表推断任意用户项目均可下载。\n\n来源：[保存帖1](https://x.com/i/status/1518709737990377484)。'], ['by-type/file-upload.md', '插件 fuzz 的 fopen 告警需区分路径和网络消费者', '图可见插件警告、服务器路径、URL 输入与域名解析失败，并有 active installs 标记。\n\n给每个输入绑定函数调用、错误原文、认证状态及实际 I/O；getaddrinfo 失败不能证明回连，文件路径警告也不证明读取字节或执行。安装量标签不是受影响数量，不能把全部 warning 升级为 SSRF/LFI/RCE。\n\n来源：[保存帖1](https://x.com/i/status/1518715114857373703)、[保存帖2](https://x.com/i/status/1518924350686064640)。'], ['discovery/web-and-api.md', 'JavaScript URL 筛选需核查询后缀和命令形状', '正文含域名空格、拆开的选项以及 .js 正则筛选；另帖用宽泛匹配。\n\n区分来源 URL、路径扩展、查询后缀、MIME 和状态，宽泛点号或仅行尾筛选都可误分。保留原命令中的格式问题而不当作已运行，结构化输出再匹配字段；ApiKey 等字符串仍只是消费者线索。\n\n来源：[保存帖1](https://x.com/i/status/1518746750055587840)、[保存帖2](https://x.com/i/status/1519691349636780032)。'], ['source-audit.md', '源码与黑盒功能发现要连接同一业务消费者', '正文强调结合代码与黑盒，以及优先研究独有功能。\n\n先为业务动作定义主体、对象、状态与输入，再从源码追解析/权限，和黑盒请求及持久结果对应。源码疑点、功能新颖或参数可改均非漏洞充分证据；已保存的是方法方向，没有实现时不补造具体缺陷。\n\n来源：[保存帖1](https://x.com/i/status/1518906946526625792)、[保存帖2](https://x.com/i/status/1518973366379683842)。'], ['discovery/client-and-cloud.md', '404 主机上的文档线索可指向另一协议入口', '正文称长 PDF 导向 JNLP 和 Java 产品登录，再称弱凭据带来设备管理权限。\n\n根路径 404 不等于整个服务无功能；保存文档版本、具体入口、协议和客户端所连服务。下载/打开 JNLP 会执行远端应用，需单独许可，资料整理不运行；缺少实际请求时不能把故事补成当前服务验证。\n\n来源：[保存帖1](https://x.com/i/status/1518946904851513345)。'], ['by-type/idor-access-control.md', '管理设备数量不能替代管理员动作边界', '同一正文把管理界面与近九千设备全控制联系起来，没有具体设备操作证据。\n\n分别验证登录角色、设备所属租户、可读数据、下发操作与最终权限消费者。库存数不说明每台在线、受控或可操作，弱凭据登录也不自动证明全量设备控制；影响仅覆盖有证据的自有对象与动作。\n\n来源：[保存帖1](https://x.com/i/status/1518946904851513345)。'], ['by-type/business-logic.md', '大小写与拼写路由变化须对照同一限流动作', '正文把不同 casing 与拼写的注册路径作为 rate limit 线索。\n\n先确认各路径触发同一注册消费者及相同身份/对象，再比较限流键、状态与持久效果。不同拼写可能命中不同处理器或错误页，HTTP 成功不说明速率配额被绕过；验证采用少量受控对照，不进行高频请求。\n\n来源：[保存帖1](https://x.com/i/status/1518960082024771584)。'], ['by-type/crlf-response-splitting.md', 'CRLF 设置跨子域 Cookie 需要响应和域作用域链', '正文把某子域响应拆分、另一子域的 Cookie XSS 串到接管；图仅严重度变化。\n\n证明输入经解码进入响应头边界，实际 Set-Cookie 的 Domain、Path、有效期及浏览器接收条件，再核消费者收到的是哪一 Cookie。两个子域相似不自动允许共享 Cookie，等级变更也不证明完整链。\n\n来源：[保存帖1](https://x.com/i/status/1519020775424106497)。'], ['by-type/authn-session.md', 'Cookie XSS 加 autocomplete 不自动泄漏凭据', '正文在重定向到登录和启用自动填充后直接声称 ATO。\n\n分别核脚本执行身份、Cookie 可读性、登录表单来源、浏览器填充条件、字段可观察性及有效会话发行。出现 autocomplete 属性不保证密码已填入或可读，不能把独立能力相加为接管；没有每一步消费者证据时限定为链假设。\n\n来源：[保存帖1](https://x.com/i/status/1519020775424106497)。'], ['by-type/csrf.md', 'CSRF 修改资料后需验证存储和受害者渲染', '保存步骤把 CSRF 改 profile name、切换 beta/重定向和 stored XSS 相连。\n\n核真实浏览器携带身份的请求、CSRF 约束、资料持久化与另一自有主体的渲染，再分别确认 beta 状态和跳转。修改成功、保存载荷和脚本执行不是同一结果；一键触发与奖励也不能补足完整权限影响。\n\n来源：[保存帖1](https://x.com/i/status/1519029368240095233)。'], ['business-modeling.md', '支付网关跳转前的步骤不证明低价购买成立', '正文只保存加购物车、选择支付方式和跳转第三方网关三步，后续未保存。\n\n区分购物车报价、支付意图、服务端订单、结算回执与履约；最终金额和商品状态必须绑定同一订单。不能补造金额修改或回调漏洞，题名声称低价买任意物品并未由这三步证明；缺失续篇按用户口径计覆盖。\n\n来源：[保存帖1](https://x.com/i/status/1519053797175267328)。'], ['by-type/waf-bypass.md', '额外等号导致状态变化要核参数实际解析', '正文比较参数值前额外等号时的 403 与 200。\n\n保存原始查询、边缘规则所见字符、后端参数名和值及最终 DOM。额外等号可能改变值内容与规则匹配，200 只说明该请求未按相同方式被拒；没有脚本消费者或事件对照，不证明 XSS 或通用 WAF 绕过。\n\n来源：[保存帖1](https://x.com/i/status/1519073738289037318)。'], ['source-audit.md', 'IDA 函数颜色与危险调用候选需追实际数据流', 'VulFi 图可见函数类别颜色、函数列表与 start 附近汇编，没有实际缺陷证明。\n\n将导入函数、调用点、参数来源、长度约束和运行路径分别核验；出现 memcpy/strcpy 等符号不说明参数可控或越界。插件高亮帮助定位候选，仍需源码/反汇编上下文与受控消费者证据，不能把颜色等同漏洞等级。\n\n来源：[保存帖1](https://x.com/i/status/1519077626975031298)、[保存帖2](https://x.com/i/status/1519087955813736448)。'], ['by-type/sql-injection.md', 'SQLMap 数据库名称输出仍需绑定注入请求', '图显示查询输出长度及多个数据库名称；正文给出发现与筛选后交给工具的流程。\n\n保存入口、参数、身份、数据库判定方法和无害对照，区分工具推断与服务器返回。部分 stdout 支持历史枚举主张，却不能证明任意记录可读、所有资产都存在 SQL 注入或当前仍可利用，不执行后续数据提取。\n\n来源：[保存帖1](https://x.com/i/status/1519121886575308801)。'], ['by-type/waf-bypass.md', '特定 CRS 和字符变换主张缺少原始链时不泛化', '正文声称修改 LiteSpeed/ModSecurity CRS 与字符组合可绕过，实际片段留在未保存评论。\n\n需绑定网关版本、规则、请求编码、后端解码和浏览器消费者；响应没有拦截不等于脚本执行。已保存的是历史主张，不补写评论载荷，也不据此宣称任意部署均可绕过。\n\n来源：[保存帖1](https://x.com/i/status/1519187833533177857)。'], ['scope-and-rules.md', '第三方脚本信任关系不自动继承测试许可', '正文称攻击第三方脚本可得到两家奖励，没有具体授权或请求。\n\n保存脚本加载来源、版本、发布控制、浏览器权限和两个项目各自允许范围。第一方信任第三方内容提供供应链假设，却不授权测试第三方基础设施；单一脚本问题是否影响另一方需要消费者与政策的独立证据。\n\n来源：[保存帖1](https://x.com/i/status/1519203729278480384)。'], ['by-type/idor-access-control.md', '邀请角色参数要约束到邀请者的有效权限', '正文称拥有 Add member 权限的用户修改邀请 role 为 Owner；图仅 P1 New，仍在评估。\n\n核邀请者可授予的角色集合、服务端绑定、邀请接受后的实际成员状态，再确认所有者限定动作。客户端字段可改、邀请提交成功和真正获得 Owner 权限分开验证，不能由未完成评估的标题直接推导全组织控制。\n\n来源：[保存帖1](https://x.com/i/status/1519230627496677376)。'], ['scope-and-rules.md', '仿登录页和文档下载需区分诱导界面与执行结果', 'O365-Doppelganger 图显示类似登录界面和打开政策文档的确认窗口，没有凭据流或执行结果。\n\n分别保存真实页面来源、下载文件类型、用户交互与进程结果。视觉相似不证明可信来源，也不证明秘密提交或代码执行；社工与文档投放必须有具体授权，整理截图不触发下载、打开或向他人发送。\n\n来源：[保存帖1](https://x.com/i/status/1519303963014844417)。'], ['by-type/xss.md', '混合内容处理与事件触发按实际浏览器核验', '历史正文把 Chrome/Firefox 的事件差异概括为固定规律，未保存版本与对照。\n\n核元素、资源类型、原方案、自动升级或阻断、控制台和实际事件；网络未加载与 DOM 事件执行分开。不同浏览器或版本行为不能由历史一句话确定。规范核验：[MDN 混合内容](https://developer.mozilla.org/en-US/docs/Web/Security/Defenses/Mixed_content)。\n\n来源：[保存帖1](https://x.com/i/status/1519360969591427078)。'], ['by-type/xss.md', '命令行 XSS 二分标签不能取代浏览器确认', '截图在历史 URL、查询去重和多参数替换后打印 Vulnerable/Not Vulnerable，没有浏览器执行画面。\n\n保留原 URL、每个参数、编码层与去重依据；同时替换多个参数会丢失因果归属。stdout 分类可能只是匹配规则，负结果也不覆盖其他状态与 DOM sink；逐一回到真实响应和浏览器消费者。\n\n来源：[保存帖1](https://x.com/i/status/1519413198138531841)、[保存帖2](https://x.com/i/status/1519459252326342656)、[保存帖3](https://x.com/i/status/1519640824295821312)。'], ['scope-and-rules.md', 'BITB 中仿地址栏不能证明真实浏览器来源', '图片把两个相似 Facebook 窗口标为 phishing 与 real，但没有真实顶层来源或凭据交换。\n\n区分页面绘制的窗口元素与浏览器可信界面，核实际顶层 URL、进程/窗口身份及提交目的地。地址栏视觉相似与有效 origin 不同；示例仅提示 UI 欺骗边界，不部署模板、采集真实凭据或发送仿登录链接。\n\n来源：[保存帖1](https://x.com/i/status/1519439841817202689)。'], ['by-type/lfi-path-traversal.md', '上传脚本到 LFI 后还需文件解释消费者', '正文用上传 PHP 片段声称 LFI 可变 RCE，没有实际读取或执行结果。\n\n分别确认上传路径/重命名、权限、文件可读、读取 API 与 include/执行解释器。返回脚本文本不等于执行，客户端路径也不说明服务器文件位置；只在自有样本中确认消费者，不能靠扩展名把文件读升级为 RCE。\n\n来源：[保存帖1](https://x.com/i/status/1519562219784400896)。'], ['by-type/desktop-client.md', '内存事件时间线要保留证据源和因果限制', 'RipRaw 相关图为云节点内存界面，含矿工引用、SSM 进程事件和部分命令日志。\n\n绑定镜像哈希、采集时间、时区、事件提取器、进程与文件；告警标签、命令字符串和相邻时间不是同一行为的完整因果链。图中时间线可指导取证检查，但不证明新节点已被入侵，也不执行可见命令。\n\n来源：[保存帖1](https://x.com/i/status/1519666433772470275)。'], ['experiment-design.md', 'URL 分类器的 0.89 accuracy 不证明 XSS', '图列两类 precision、recall、F1 与 1,923 个样本，正文称按 URL 词汇预测风险。\n\n明确标签含义、训练/测试分离、来源重复、误报/漏报及实际目标分布；评分只反映该评估集。概率可用于候选排序，不能证明脚本执行或目标覆盖，不能把高分当作替代浏览器消费者验证。\n\n来源：[保存帖1](https://x.com/i/status/1519682355996340224)。'], ['discovery/records-and-incremental.md', '开放端口管道交给 HTTP 工具前先核协议', '正文从端口扫描 stdout 筛 Open，经文本替换交给 HTTP 探测和模板工具。\n\n保留主机、端口、IPv6 和输出格式，验证转换后记录是否仍绑定原服务。开放端口可能是非 HTTP 协议，过滤和后续工具会遗漏；模板结束也不代表全部服务验证，分别保存协议判定、失败与产物。\n\n来源：[保存帖1](https://x.com/i/status/1519723771627806720)。'], ['by-type/waf-bypass.md', '挑战页观察不能证明所有防护部署可绕过', '正文以所有 Under Attack/Rate limiting 站点为概括，图仅浏览器挑战等待页。\n\n保存触发条件、浏览器状态、会话、挑战响应和受限功能结果。等待页不显示绕过方法、限流键或最终成功；特定历史页面不能推广到全部防护部署，也不补造未保存线程的步骤。\n\n来源：[保存帖1](https://x.com/i/status/1519768264779476994)。'], ['by-type/cmd-injection-rce.md', '302 响应体中的命令结果应与输入和身份绑定', '两张请求/响应图在 auth 用户字段引入动态求值，并以另一个参数选择不同命令；302 响应体分别含进程身份和目录清单，第三张只为报告邮件。\n\n重定向状态不抹去响应体证据，比较输入变化与输出变化，但仍要核是否带已有会话、运行主体与受影响代码。遮挡部分不推断无认证或全服务器控制；不复制 Cookie、执行片段或外部命令，修复主张需同条件复测证据。\n\n来源：[保存帖1](https://x.com/i/status/1519783358192140302)。'], ['source-audit.md', '异常分支的参数名输出需要独立 HTML 编码', 'CTF 源码图的正常分支对某参数值调用 html.escape，异常分支把请求参数名拼接后直接放入 HTML。\n\n分别追正常与异常路径、输入类型和异常是否可达，核参数名经解析后是否进入未编码响应。正常值编码不保护另一输入的错误页面；代码支持候选数据流，实际异常触发和浏览器执行尚需自有离线样本，不能直接认定远端已确认。\n\n来源：[保存帖1](https://x.com/i/status/1519813047052914689)。'], ['by-type/ssrf.md', '特殊 IP 表示应在实际 URL 消费者中规范化', '正文把短 IPv4、数值进制、0 与 IPv6 未指定地址列为回环绕过。\n\n按实际 URL/网络库规范化后检查地址类别，保留重定向及最终连接地址。WHATWG 解析有短形式和数值进制规则，但不能替代任意服务端库；0.0.0.0 与 :: 为未指定地址，不能一律等同 127.0.0.1，其连接语义还需环境证据。规范核验：[WHATWG URL](https://url.spec.whatwg.org/#ipv4-parser)。\n\n来源：[保存帖1](https://x.com/i/status/1519814460331991041)、[保存帖2](https://x.com/i/status/1520606109358120960)。'], ['cloud/cloud-misconfiguration.md', '公开 S3 搜索结果要核归属和具体访问能力', '正文只推荐公开 bucket 搜索站点，没有对象或响应。\n\n区分索引记录、桶归属、列表能力、对象读取、写入和是否预期公开。公开命中不证明秘密暴露或允许测试，历史索引也不说明当前策略；每种影响都需范围内最小对象证据，不遍历、写入或使用发现的材料。\n\n来源：[保存帖1](https://x.com/i/status/1519936550846746624)。'], ['impact-and-acceptance.md', 'Jira CVE 的通用评分与平台优先级分别说明', '一张图仅 P5 报告，另一张历史 NVD 条目说明特定 Jira 版本的文件读取，CVSS 5.3 与低机密性影响。\n\n保存历史受影响版本、可读文件和评分条件，再对照本次部署、文件内容和平台规则。CVE 或 CVSS 的分类不是当前实例可利用性证明，平台 P5 也不推翻缺陷机制；没有实际请求时不补成全量敏感文件读取。\n\n来源：[保存帖1](https://x.com/i/status/1516103970124668937)。']]
ids={pid for row in json.loads((W/"batch-0128.json").read_text()) for pid in row["post_ids"]}
urls=[pid for _,_,body in facets for pid in re.findall(r"https://x\.com/i/status/(\d+)",body)]
assert len(urls)==121 and all(pid in ids for pid in urls)
assert len({title for _,title,_ in facets})==len(facets)
grouped=defaultdict(list)
for f,title,body in facets:
 p=T/"references"/f
 assert p.is_file() and ("## "+title) not in p.read_text(),(f,title)
 grouped[p].append("\n\n## "+title+"\n\n"+body+"\n")
community=T/"references/research/community-distillation.md"
marker="\n## 首轮提炼范围与未采纳内容\n"
c=community.read_text();assert c.count(marker)==1
routes=[]
for f,title,body in facets:
 summary=body.split("\n")[0].split("。")[0]+"。"
 summary=summary.replace("|","｜")
 assert "|" not in summary and "\n" not in summary
 routes.append(f"| {title} | {summary} | [方法条目](../{f}) |")
for p,parts in grouped.items():p.write_text(p.read_text()+"".join(parts))
community.write_text(c.replace(marker,"\n"+"\n".join(routes)+"\n"+marker,1))
print("Added",len(facets),"facets/routes to",len(grouped),"topics;",len(urls),"batch-bound URLs")

